def lower_bound(values, target):
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def merge_intervals(intervals):
    items = sorted((int(a), int(b)) for a, b in intervals)
    merged = []
    for start, end in items:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def run_length(values):
    result = []
    for v in values:
        if result and result[-1][0] == v:
            result[-1] = (v, result[-1][1] + 1)
        else:
            result.append((v, 1))
    return result


def stable_unique(values):
    seen = set()
    result = []
    for v in values:
        if v not in seen:
            seen.add(v)
            result.append(v)
    return result
